│       ├── _runtime.ts         # Helpers: getEnv(), withTimeout()
│       └── _builtin/           # Hand-written flows
│           ├── login.ts        # Idempotent login + event handlers
│           └── anchorStartThenEnd.ts  # Live anchor orchestration
├── profiles/                   # Framework selection layer
