/*
 * HTML 卡片统一样式（通用版）
 * 所有产出物共享同一份视觉基线，agent 生成时按 template.html 组装。
 * 修改前请阅读 references/design-rules.md 的 16 条硬规则。
 *
 * 换主色只改下面 3 个变量：--brand / --brand-deep / --brand-soft
 * 其余语义色（warn/ok/danger）建议保持，它们与规则 3/15 的语义绑定。
 */

:root {
  --brand: #0052D9;
  --brand-soft: #E8F0FE;
  --brand-deep: #003A99;
  --ink: #1F2329;
  --ink-2: #4E5969;
  --ink-3: #86909C;
  --line: #E5E6EB;
  --bg: #F7F8FA;
  --surface: #FFFFFF;
  --warn: #FF7D00;
  --warn-soft: #FFF7E8;
  --ok: #00B42A;
  --ok-soft: #E8FFEA;
  --danger: #F53F3F;
  --danger-soft: #FFECE8;
}
* { box-sizing: border-box; }
body {
  margin: 0;
  padding: 32px 20px;
  font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Microsoft YaHei", "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--ink);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
.container { max-width: 880px; margin: 0 auto; }

/* ========== 顶部 Banner ========== */
.banner {
  background: linear-gradient(135deg, var(--brand) 0%, var(--brand-deep) 100%);
  color: #fff;
  padding: 28px 32px;
  border-radius: 16px 16px 0 0;
  position: relative;
  overflow: hidden;
}
.banner::after {
  content: "";
  position: absolute;
  right: -40px; top: -40px;
  width: 200px; height: 200px;
  background: rgba(255,255,255,0.06);
  border-radius: 50%;
}
/* Banner 品牌区：思研横版组合标志 + 角色行（logo 为品牌资产，勿改路径与配色） */
.banner .banner-brand {
  display: flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 10px 0;
  position: relative;
  z-index: 1;
}
.banner .banner-logo {
  display: inline-flex;
  align-items: center;
  height: 40px;
  padding: 4px 10px;
  border-radius: 8px;
  background: #fff;          /* 标志为品牌蓝 #0052D9，深色 banner 上需白色衬底 */
  flex-shrink: 0;
}
.banner .banner-logo svg { display: block; height: 32px; width: auto; }
/* 品牌区存在时，brand-tag 的下边距交由 .banner-brand 统一管理 */
.banner .banner-brand .brand-tag { margin: 0; }

/* Banner 顶部品牌+角色行（纯白小字，见规则 14/16；不需要品牌行可整段删除） */
.banner .brand-tag {
  font-size: 13px;
  color: rgba(255,255,255,0.85);
  margin: 0 0 10px 0;
  letter-spacing: 0.3px;
  position: relative;
  z-index: 1;
}
.banner .brand-tag .sep { margin: 0 6px; opacity: 0.6; }
.banner .title {
  font-size: 24px; font-weight: 600;
  margin: 0 0 4px 0;
}
.banner .subtitle {
  font-size: 14px; opacity: 0.9; margin: 0;
}
.banner .meta {
  margin-top: 14px; font-size: 13px;
  opacity: 0.85;
  display: flex; gap: 20px; flex-wrap: wrap;
}
.banner .meta span {
  display: inline-flex; align-items: center; gap: 6px;
}
.banner .meta i.bi {
  font-size: 14px; opacity: 0.9;
}

/* ========== 主体 ========== */
.body {
  background: var(--surface);
  padding: 28px 32px 8px;
  border-radius: 0 0 16px 16px;
  box-shadow: 0 1px 4px rgba(0,0,0,0.04);
}
section { margin-bottom: 28px; }
section:last-child { margin-bottom: 0; }

/* 章节大标题（h2）—— 序号 + 标题，无左竖条 */
h2.section-title {
  font-size: 17px; font-weight: 600;
  color: var(--ink);
  margin: 0 0 14px 0;
  line-height: 1.35;
  display: flex;
  align-items: baseline;
  gap: 10px;
}
h2.section-title .idx {
  color: var(--brand);
  font-weight: 700;
  font-size: 18px;
  letter-spacing: 0.5px;
}

/* 每个模块的重点句 —— 放在模块正文之前；无固定前缀，见规则 2 */
.lead {
  font-size: 13.5px;
  color: var(--ink-2);
  line-height: 1.7;
  margin: 0 0 14px 0;
  padding: 12px 14px;
  background: #FAFBFC;
  border-radius: 6px;
}
.lead strong { color: var(--ink); font-weight: 600; }

/* ========== 表格（含 KV 型两列表；KV 型必须带 thead） ========== */
table.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 13.5px;
}
table.data-table th {
  background: #FAFBFC;
  color: var(--ink-2);
  font-weight: 500;
  text-align: left;
  padding: 10px 12px;
  border-bottom: 2px solid var(--line);
  font-size: 13px;
}
table.data-table td {
  padding: 12px;
  border-bottom: 1px solid var(--line);
  vertical-align: top;
  color: var(--ink);
}
table.data-table tr:last-child td { border-bottom: none; }
table.data-table tr:hover td { background: #FAFBFC; }

/* KV 型表格：左列字段名（灰字 500 weight），右列内容。用 td.kv-key */
table.data-table td.kv-key {
  color: var(--ink-2);
  font-weight: 500;
}

/* 徽章 */
.pill {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 500;
  line-height: 1.5;
}
.pill-ok { background: var(--ok-soft); color: var(--ok); }
.pill-warn { background: var(--warn-soft); color: var(--warn); }
.pill-danger { background: var(--danger-soft); color: var(--danger); }
.pill-brand { background: var(--brand-soft); color: var(--brand); }
.pill-recommend { background: var(--brand); color: #fff; }

/* ========== 时间轴（精简版：每块 + 目标行 + 无 icon bullets） ========== */
.timeline {
  position: relative;
  padding-left: 24px;
}
.timeline::before {
  content: "";
  position: absolute;
  left: 6px; top: 8px; bottom: 8px;
  width: 2px; background: var(--line);
}
.tl-item { position: relative; padding-bottom: 20px; }
.tl-item:last-child { padding-bottom: 0; }
.tl-item::before {
  content: "";
  position: absolute;
  left: -22px; top: 7px;
  width: 10px; height: 10px;
  border-radius: 50%;
  background: var(--brand);
  border: 2px solid #fff;
  box-shadow: 0 0 0 2px var(--brand);
}
.tl-item .tl-head {
  font-size: 14px; font-weight: 600;
  color: var(--ink);
  margin-bottom: 4px;
  line-height: 1.4;
}
.tl-item .tl-head .week {
  color: var(--brand);
  margin-right: 6px;
}
.tl-item .tl-head .sep { color: var(--ink-3); margin: 0 4px; }
.tl-item .tl-goal {
  font-size: 13px;
  color: var(--ink-2);
  margin-bottom: 8px;
}
.tl-item .tl-goal strong { color: var(--ink); font-weight: 500; }
.tl-item .tl-list {
  margin: 0;
  padding-left: 20px;
  font-size: 13px;
  color: var(--ink-2);
  line-height: 1.85;
}
.tl-item .tl-list li { padding-left: 2px; }

/* ========== 提示条（2 色：默认蓝｜warn 黄，无 icon） ========== */
.callout {
  padding: 12px 16px;
  border-radius: 8px;
  border-left: 3px solid var(--brand);
  font-size: 13.5px;
  line-height: 1.7;
  background: var(--brand-soft);
  color: var(--ink);
  margin-top: 14px;
}
.callout strong.title {
  color: var(--brand-deep);
  font-weight: 600;
  margin-right: 4px;
}
.callout-warn { border-color: var(--warn); background: var(--warn-soft); color: #1F2329; }
.callout-warn strong.title { color: #7A4300; }

/* ========== 通用 bullet 列表 ==========
 * 高频用法：<li><strong>标签：</strong>描述文字</li>
 * 左标签深黑加粗 + 冒号后微空隙，扫读时锚点清晰
 */
ul.plain-list {
  margin: 0;
  padding-left: 20px;
  font-size: 13.5px;
  color: var(--ink-2);
  line-height: 1.85;
}
ul.plain-list li { margin: 4px 0; padding-left: 2px; }
ul.plain-list li strong { color: var(--ink); font-weight: 600; }
ul.plain-list li strong:first-child { margin-right: 4px; }

/* callout 内嵌 plain-list：紧贴上文的 title 行，无额外 margin */
.callout ul.plain-list { margin-top: 8px; color: inherit; }
.callout ul.plain-list li { color: inherit; }

/* ========== 决策标签（用于条件枚举 / 决策分支的结论词，无底色） ==========
 * 用法：<li><strong>若两点都谈成：</strong><span class="tag-ok">可接 ✓</span> 说明文字…</li>
 * 三档：ok（正向 / 推荐 / 可接）｜warn（谨慎 / 有条件 / 观望）｜bad（不推荐 / 不接 / 红线）
 * 关键：只染字色，不加底色。要与 plain-list 搭配使用，禁止塞进 callout。
 */
.tag-ok, .tag-warn, .tag-bad {
  font-weight: 600;
  margin-right: 4px;
}
.tag-ok { color: var(--ok); }
.tag-warn { color: var(--warn); }
.tag-bad { color: var(--danger); }

.disclaimer {
  text-align: center;
  font-size: 11.5px;
  color: var(--ink-3);
  margin-top: 20px;
  padding: 14px 0;
}

.disclaimer a {
  color: var(--brand);
  text-decoration: none;
  font-weight: 600;
}

.disclaimer a:hover {
  text-decoration: underline;
}

/* 打印友好 */
@media print {
  body { padding: 0; background: #fff; }
  .banner { border-radius: 0; }
  .body { border-radius: 0; box-shadow: none; }
}

047202cb0534495f00198b7b5d7e5a2819a194a8.text:
/**
 * 云知 MCP 参数校验和修复工具
 * 用于检查和修复常见的 MCP 调用参数错误
 */

// ============ 类型定义 ============

interface ValidationError {
  field: string;
  message: string;
  suggestion: string;
  severity: 'error' | 'warning';
}

interface ValidationResult {
  valid: boolean;
  errors: ValidationError[];
  fixedArgs?: object;
}

interface ApplyUploadArgs {
  parent_entry_id?: string;
  name?: string;
  mime_type?: string;
  size?: number;
  file_id?: string;
  upload_type?: string;
}

interface CreateBlockDescendantArgs {
  entry_id?: string;
  parent_block_id?: string;
  descendant?: any[];
  children?: string[];
  index?: number;
}

interface Block {
  block_id?: string;
  block_type?: string;
  children?: string[];
  [key: string]: any;
}

// ============ 常量定义 ============

// 叶子节点类型（不支持 children）
const LEAF_BLOCK_TYPES = new Set([
  'h1', 'h2', 'h3', 'h4', 'h5',
  'code', 'image', 'attachment', 'video',
  'divider', 'mermaid', 'plantuml'
]);

// 容器类型（必须有 children）
const CONTAINER_BLOCK_TYPES = new Set([
  'callout', 'table', 'table_cell',
  'column_list', 'column', 'toggle'
]);

// 块类型到内容字段的映射
const BLOCK_TYPE_TO_FIELD: Record<string, string> = {
  'p': 'text',
  'h1': 'heading1',
  'h2': 'heading2',
  'h3': 'heading3',
  'h4': 'heading4',
  'h5': 'heading5',
  'bulleted_list': 'bulleted',
  'numbered_list': 'numbered',
  'code': 'code',
  'toggle': 'toggle',
  'callout': 'callout',
  'task': 'task',
  'table': 'table',
  'table_cell': 'table_cell',
  'column_list': 'column_list',
  'column': 'column',
  'divider': 'divider',
  'mermaid': 'mermaid',
  'plantuml': 'plantuml'
};

// MIME 类型映射
const EXT_TO_MIME: Record<string, string> = {
  '.md': 'text/markdown',
  '.markdown': 'text/markdown',
  '.txt': 'text/plain',
  '.json': 'application/json',
  '.pdf': 'application/pdf',
  '.doc': 'application/msword',
  '.docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
  '.xls': 'application/vnd.ms-excel',
  '.xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.gif': 'image/gif',
  '.svg': 'image/svg+xml'
};

// ============ 校验器 ============

/**
 * 校验 apply_upload 参数
 */
export function validateApplyUpload(
  args: ApplyUploadArgs,
  context: { isUpdate: boolean; currentEntryId?: string; fileId?: string }
): ValidationResult {
  const errors: ValidationError[] = [];
  const fixedArgs = { ...args };

  // 1. 必填字段检查
  if (!args.parent_entry_id) {
    errors.push({
      field: 'parent_entry_id',
      message: '缺少 parent_entry_id',
      suggestion: context.isUpdate
        ? `更新文件时，parent_entry_id 应填写当前文件的 entry_id: "${context.currentEntryId}"`
        : '新建文件时，parent_entry_id 应填写父目录的 entry_id',
      severity: 'error'
    });
  }

  if (!args.name) {
    errors.push({
      field: 'name',
      message: '缺少文件名 name',
      suggestion: '请提供文件名，包含扩展名，如 "document.md"',
      severity: 'error'
    });
  }

  // 2. ⚠️ 关键：文件大小检查
  if (args.size === undefined || args.size === null) {
    errors.push({
      field: 'size',
      message: '【关键】缺少文件大小 size',
      suggestion: '必须指定文件大小（字节数）。可通过 fs.statSync(path).size 获取',
      severity: 'error'
    });
  } else if (args.size <= 0) {
    errors.push({
      field: 'size',
      message: '文件大小必须大于 0',
      suggestion: `当前值: ${args.size}，请检查文件是否存在或为空`,
      severity: 'error'
    });
  }

  // 3. MIME 类型检查
  if (!args.mime_type && args.name) {
    const ext = args.name.substring(args.name.lastIndexOf('.')).toLowerCase();
    const guessedMime = EXT_TO_MIME[ext];
    if (guessedMime) {
      fixedArgs.mime_type = guessedMime;
      errors.push({
        field: 'mime_type',
        message: '缺少 mime_type，已自动推断',
        suggestion: `根据文件扩展名 "${ext}" 推断为 "${guessedMime}"`,
        severity: 'warning'
      });
    } else {
      fixedArgs.mime_type = 'application/octet-stream';
      errors.push({
        field: 'mime_type',
        message: '缺少 mime_type，使用默认值',
        suggestion: '无法识别的扩展名，使用 "application/octet-stream"',
        severity: 'warning'
      });
    }
  }

  // 4. upload_type 检查
  if (!args.upload_type) {
    fixedArgs.upload_type = 'PRE_SIGNED_URL';
    errors.push({
      field: 'upload_type',
      message: '缺少 upload_type，已自动设置',
      suggestion: '已设置为 "PRE_SIGNED_URL"',
      severity: 'warning'
    });
  }

  // 5. ⚠️ 关键：更新文件时的参数检查
  if (context.isUpdate) {
    if (!args.file_id) {
      errors.push({
        field: 'file_id',
        message: '【关键】更新文件时缺少 file_id',
        suggestion: `更新文件必须提供 file_id。可通过 describe_entry 获取条目详情，返回的 target_id 即为 file_id${context.fileId ? `，当前文件的 file_id 应为: "${context.fileId}"` : ''}`,
        severity: 'error'
      });
    }

    // 检查 parent_entry_id 是否正确（更新时应该是当前文件的 entry_id）
    if (args.parent_entry_id && context.currentEntryId &&
        args.parent_entry_id !== context.currentEntryId) {
      errors.push({
        field: 'parent_entry_id',
        message: '【关键】更新文件时 parent_entry_id 设置错误',
        suggestion: `更新文件时，parent_entry_id 应填写当前文件自己的 entry_id "${context.currentEntryId}"，而不是父目录的 entry_id`,
        severity: 'error'
      });
      fixedArgs.parent_entry_id = context.currentEntryId;
    }
  } else {
    // 新建文件时不应该有 file_id
    if (args.file_id) {
      errors.push({
        field: 'file_id',
        message: '新建文件时不应提供 file_id',
        suggestion: 'file_id 仅在更新已有文件时使用，新建文件请移除此参数',
        severity: 'warning'
      });
      delete fixedArgs.file_id;
    }
  }

  return {
    valid: errors.filter(e => e.severity === 'error').length === 0,
    errors,
    fixedArgs
  };
}

/**
 * 校验 create_block_descendant 参数
 */
export function validateCreateBlockDescendant(args: CreateBlockDescendantArgs): ValidationResult {
  const errors: ValidationError[] = [];
  const fixedArgs = { ...args };
  const fixedDescendant = args.descendant ? [...args.descendant] : [];

  // 1. 必填字段检查
  if (!args.entry_id) {
    errors.push({
      field: 'entry_id',
      message: '缺少 entry_id',
      suggestion: '请提供目标文档的 entry_id',
      severity: 'error'
    });
  }

  if (!args.descendant || args.descendant.length === 0) {
    errors.push({
      field: 'descendant',
      message: '缺少 descendant 数组或数组为空',
      suggestion: 'descendant 必须包含至少一个块定义',
      severity: 'error'
    });
    return { valid: false, errors };
  }

  // 2. 遍历检查每个块
  const blockIds = new Set<string>();
  const childrenRefs = new Set<string>();

  for (let i = 0; i < args.descendant.length; i++) {
    const block = args.descendant[i] as Block;
    const blockPath = `descendant[${i}]`;

    // 2.1 检查 block_id
    if (!block.block_id) {
      errors.push({
        field: `${blockPath}.block_id`,
        message: '块缺少 block_id',
        suggestion: '每个块必须有唯一的 block_id（临时ID），如 "blk_1"',
        severity: 'error'
      });
    } else {
      if (blockIds.has(block.block_id)) {
        errors.push({
          field: `${blockPath}.block_id`,
          message: `block_id "${block.block_id}" 重复`,
          suggestion: '每个块的 block_id 必须唯一',
          severity: 'error'
        });
      }
      blockIds.add(block.block_id);
    }

    // 2.2 检查 block_type
    if (!block.block_type) {
      errors.push({
        field: `${blockPath}.block_type`,
        message: '块缺少 block_type',
        suggestion: '请指定块类型，如 "p", "h1", "callout" 等',
        severity: 'error'
      });
      continue;
    }

    // 2.3 ⚠️ 关键：检查叶子节点是否错误地包含 children
    if (LEAF_BLOCK_TYPES.has(block.block_type) && block.children && block.children.length > 0) {
      errors.push({
        field: `${blockPath}.children`,
        message: `【关键】${block.block_type} 是叶子节点，不能包含 children`,
        suggestion: `标题块 (h1-h5)、代码块 (code)、分割线 (divider)、图表块 (mermaid/plantuml) 等不支持子节点。请移除 children: ${JSON.stringify(block.children)}`,
        severity: 'error'
      });

      // 自动修复：移除 children
      const fixedBlock = { ...fixedDescendant[i] };
      delete fixedBlock.children;
      fixedDescendant[i] = fixedBlock;
    }

    // 2.4 检查容器类型是否缺少 children
    if (CONTAINER_BLOCK_TYPES.has(block.block_type) && (!block.children || block.children.length === 0)) {
      errors.push({
        field: `${blockPath}.children`,
        message: `${block.block_type} 是容器类型，必须指定 children`,
        suggestion: `容器类型块（callout, table, table_cell, column_list, column, toggle）必须包含子块。服务端会自动创建空白子块，但建议显式指定。`,
        severity: 'warning'
      });
    }

    // 2.5 收集 children 引用
    if (block.children) {
      for (const childId of block.children) {
        childrenRefs.add(childId);
      }
    }

    // 2.6 检查内容字段是否正确
    const expectedField = BLOCK_TYPE_TO_FIELD[block.block_type];
    if (expectedField && !block[expectedField]) {
      // 对于需要内容的块类型，检查是否有内容
      if (!CONTAINER_BLOCK_TYPES.has(block.block_type) && block.block_type !== 'divider') {
        errors.push({
          field: `${blockPath}.${expectedField}`,
          message: `${block.block_type} 块缺少内容字段 "${expectedField}"`,
          suggestion: `请添加 "${expectedField}" 字段，参考: { "${expectedField}": { "elements": [{ "text_run": { "content": "文本内容" } }] } }`,
          severity: 'warning'
        });
      }
    }
  }

  // 3. 检查 children 引用的有效性
  for (const childId of childrenRefs) {
    if (!blockIds.has(childId)) {
      errors.push({
        field: 'children',
        message: `children 引用了不存在的 block_id: "${childId}"`,
        suggestion: `确保 "${childId}" 在 descendant 数组中有对应的块定义`,
        severity: 'error'
      });
    }
  }

  // 4. 检查顶层 children
  if (!args.children || args.children.length === 0) {
    // 尝试自动推断顶层 children（非被引用的块）
    const topLevelBlocks = [...blockIds].filter(id => !childrenRefs.has(id));
    if (topLevelBlocks.length > 0) {
      fixedArgs.children = topLevelBlocks;
      errors.push({
        field: 'children',
        message: '缺少顶层 children，已自动推断',
        suggestion: `根据块引用关系，推断顶层块为: ${JSON.stringify(topLevelBlocks)}`,
        severity: 'warning'
      });
    }
  }

  fixedArgs.descendant = fixedDescendant;

  return {
    valid: errors.filter(e => e.severity === 'error').length === 0,
    errors,
    fixedArgs
  };
}

/**
 * 校验 update_blocks 参数
 */
export function validateUpdateBlocks(args: { entry_id?: string; updates?: Record<string, any> }): ValidationResult {
  const errors: ValidationError[] = [];

  if (!args.entry_id) {
    errors.push({
      field: 'entry_id',
      message: '缺少 entry_id',
      suggestion: '请提供目标文档的 entry_id',
      severity: 'error'
    });
  }

  if (!args.updates || Object.keys(args.updates).length === 0) {
    errors.push({
      field: 'updates',
      message: '缺少 updates 或 updates 为空',
      suggestion: 'updates 必须包含至少一个 block_id 到更新操作的映射',
      severity: 'error'
    });
  } else if (Object.keys(args.updates).length > 20) {
    errors.push({
      field: 'updates',
      message: `updates 包含 ${Object.keys(args.updates).length} 个块，超过限制`,
      suggestion: '单次最多更新 20 个块，请分批调用',
      severity: 'error'
    });
  }

  return {
    valid: errors.filter(e => e.severity === 'error').length === 0,
    errors
  };
}

/**
 * 校验 move_blocks 参数
 */
export function validateMoveBlocks(args: {
  entry_id?: string;
  block_ids?: string[];
  parent_block_id?: string;
  after?: string;
}): ValidationResult {
  const errors: ValidationError[] = [];

  if (!args.entry_id) {
    errors.push({
      field: 'entry_id',
      message: '缺少 entry_id',
      suggestion: '请提供目标文档的 entry_id',
      severity: 'error'
    });
  }

  if (!args.block_ids || args.block_ids.length === 0) {
    errors.push({
      field: 'block_ids',
      message: '缺少 block_ids 或数组为空',
      suggestion: 'block_ids 必须包含至少一个要移动的块 ID',
      severity: 'error'
    });
  } else if (args.block_ids.length > 20) {
    errors.push({
      field: 'block_ids',
      message: `block_ids 包含 ${args.block_ids.length} 个块，超过限制`,
      suggestion: '单次最多移动 20 个块，请分批调用',
      severity: 'error'
    });
  }

  if (!args.parent_block_id) {
    errors.push({
      field: 'parent_block_id',
      message: '缺少 parent_block_id',
      suggestion: '请提供目标父节点的 block_id',
      severity: 'error'
    });
  }

  return {
    valid: errors.filter(e => e.severity === 'error').length === 0,
    errors
  };
}

// ============ 辅助函数 ============

/**
 * 格式化校验结果为可读字符串
 */
export function formatValidationResult(result: ValidationResult): string {
  const lines: string[] = [];

  if (result.valid) {
    lines.push('✅ 参数校验通过');
  } else {
    lines.push('❌ 参数校验失败');
  }

  if (result.errors.length > 0) {
    lines.push('');
    lines.push('问题列表:');
    for (const error of result.errors) {
      const icon = error.severity === 'error' ? '🔴' : '🟡';
      lines.push(`${icon} [${error.field}] ${error.message}`);
      lines.push(`   💡 ${error.suggestion}`);
    }
  }

  if (result.fixedArgs) {
    lines.push('');
    lines.push('修复后的参数:');
    lines.push(JSON.stringify(result.fixedArgs, null, 2));
  }

  return lines.join('\n');
}

/**
 * 快速修复 apply_upload 参数
 */
export function fixApplyUploadArgs(
  args: ApplyUploadArgs,
  fileInfo: { path: string; size: number; entryId?: string; fileId?: string }
): ApplyUploadArgs {
  const isUpdate = !!fileInfo.fileId;
  const ext = fileInfo.path.substring(fileInfo.path.lastIndexOf('.')).toLowerCase();
  const fileName = fileInfo.path.substring(fileInfo.path.lastIndexOf('/') + 1);

  return {
    parent_entry_id: isUpdate ? fileInfo.entryId : args.parent_entry_id,
    name: args.name || fileName,
    mime_type: args.mime_type || EXT_TO_MIME[ext] || 'application/octet-stream',
    size: fileInfo.size,
    file_id: isUpdate ? fileInfo.fileId : undefined,
    upload_type: 'PRE_SIGNED_URL'
  };
}

/**
 * 快速修复 create_block_descendant 参数
 * 移除叶子节点的 children，补全容器节点的 children
 */
export function fixCreateBlockDescendantArgs(args: CreateBlockDescendantArgs): CreateBlockDescendantArgs {
  if (!args.descendant) return args;

  const fixedDescendant = args.descendant.map(block => {
    const fixedBlock = { ...block };

    // 移除叶子节点的 children
    if (LEAF_BLOCK_TYPES.has(block.block_type) && fixedBlock.children) {
      delete fixedBlock.children;
    }

    return fixedBlock;
  });

  // 推断顶层 children
  const blockIds = new Set(fixedDescendant.map(b => b.block_id));
  const childrenRefs = new Set<string>();
  for (const block of fixedDescendant) {
    if (block.children) {
      for (const childId of block.children) {
        childrenRefs.add(childId);
      }
    }
  }
  const topLevelBlocks = [...blockIds].filter(id => !childrenRefs.has(id));

  return {
    ...args,
    descendant: fixedDescendant,
    children: args.children && args.children.length > 0 ? args.children : topLevelBlocks
  };
}

// ============ 导出 ============

export {
  ValidationError,
  ValidationResult,
  ApplyUploadArgs,
  CreateBlockDescendantArgs,
  Block,
  LEAF_BLOCK_TYPES,
  CONTAINER_BLOCK_TYPES,
  BLOCK_TYPE_TO_FIELD,
  EXT_TO_MIME
};

